{
  "concepts": [
    {
      "conditions": [],
      "definition": "The subject's traversal-occurrence profile supplies application-neutral record, relation, identity, causality, effect-boundary, frontier and refusal laws. It supplies no operational or judgment authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1443,
          "quote": "This profile owns only the application-neutral record, relation, identity,\ncausal, effect-boundary, frontier and refusal laws above.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FAuthority%20and%20adoption",
          "start_line": 1438
        }
      ],
      "key": "occurrence_profile",
      "label": "Traversal-occurrence profile"
    },
    {
      "conditions": [],
      "definition": "Complete field-reference specialization RefDomain_Sigma_occurrence(record_kind, qualified_field). O:S denotes semantic-object sort S; AnyLocal is exactly O union E union C union L union X union V union T union J; Sigma:K denotes an exact member of a closed signature population; an empty table cell permits no target in that class. ReferenceDomain, ExternalTargetKind and BasisRelation are profile-owned signature populations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 258,
          "quote": "`RefDomain_Sigma_occurrence(record_kind, qualified_field)`. Source families\nuse the exact `O/E/C/L/X/V/T/J` populations.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 251
        }
      ],
      "key": "reference_domain",
      "label": "Finite reference-domain table"
    },
    {
      "conditions": [],
      "definition": "The inherited transformation's finite external-resolution coordinates: D_ext={external_preserved, external_introduced, external_removed}; W_ext={external_resolution, domain_resolution, codomain_resolution}; Q_ext={external_identity, reference_domain, external_target_kind, resolved_target_identity, basis_relation, resolution_basis, evidence_identity}. These coordinates are separate from local deltas.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 416,
          "quote": "The external-resolution coordinates of the inherited transformation are\nclosed by this finite expansion and are not hidden inside the three\nlocal-delta rows above (P3, P4b):",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 414
        }
      ],
      "key": "external_resolution",
      "label": "External resolution and preservation witnesses"
    },
    {
      "conditions": [],
      "definition": "OccurrenceModelSubject identifies the model and exact profile basis that model_validation judges.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 281,
          "quote": "| `O:OccurrenceModelSubject.value.model_identity` | 1 |  |  | `ModelContentIdentity` | `B_adopted` |\n| `O:OccurrenceModelSubject.value.profile_basis_ref` | 1 |  |  | `TraversalOccurrenceProfileBasis` | `B_profile` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 280
        }
      ],
      "key": "occurrence_model_subject",
      "label": "OccurrenceModelSubject"
    },
    {
      "conditions": [],
      "definition": "A separately identified traversal application with traversal, functor-kind, input and application-contract references; its pre-existing identity is an occurrence seed.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1109,
          "quote": "`application identity` is the exact pre-existing `TraversalApplication`\nidentity, whose traversal and functor-kind fields equal the occurrence's.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FOccurrence%20identity",
          "start_line": 1108
        }
      ],
      "key": "traversal_application",
      "label": "TraversalApplication"
    },
    {
      "conditions": [],
      "definition": "An immutable identity for one application of a traversal, binding its exact profile basis, application, traversal, functor kind, subject binding, intended outcome, declared lineage and identity-dependency inputs.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1100,
          "quote": "id(o_n) binds (\n  exact traversal-occurrence-profile basis,\n  application identity,\n  traversal identity,\n  functor-kind identity,\n  subject-binding identity,\n  intended-outcome identity,\n  declared lineage inputs,\n  declared identity-dependency inputs\n)",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FOccurrence%20identity",
          "start_line": 1091
        }
      ],
      "key": "occurrence",
      "label": "Occurrence"
    },
    {
      "conditions": [],
      "definition": "Stable binding to an externally mutable subject, with exact authority and invalidation references.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 295,
          "quote": "| `O:SubjectBinding.value.subject_ref` | 1 |  |  | `MutableSubject` | `B_adopted` |\n| `O:SubjectBinding.value.authority_ref` | 1 |  |  | `Authority` | `B_adopted` |\n| `O:SubjectBinding.value.invalidation_ref` | 1 |  |  | `InvalidationContract` | `B_adopted` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 293
        }
      ],
      "key": "subject_binding",
      "label": "SubjectBinding"
    },
    {
      "conditions": [],
      "definition": "A bounded observation described through subject-binding, observer, evidence and observation-coordinate references; observations describe rather than replace the mutable subject.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 299,
          "quote": "| `O:Observation.value.subject_binding_ref` | 1 | `O` | `SubjectBinding` |  | `B_model` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
