        }
      ],
      "key": "observation",
      "label": "Observation"
    },
    {
      "conditions": [],
      "definition": "IntendedOutcome identifies the outcome, outcome contract and comparison basis against which bounded effect evidence is read.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 302,
          "quote": "| `O:IntendedOutcome.value.outcome_ref` | 1 |  |  | `Outcome` | `B_adopted` |\n| `O:IntendedOutcome.value.outcome_contract_ref` | 1 |  |  | `OutcomeContract` | `B_adopted` |\n| `O:IntendedOutcome.value.comparison_basis_ref` | 1 |  |  | `ComparisonBasis` | `B_adopted` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 300
        }
      ],
      "key": "intended_outcome",
      "label": "IntendedOutcome"
    },
    {
      "conditions": [],
      "definition": "Exact operation kind closing an operation contract, target sort and invalidation contract; matching labels alone do not identify the kind.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 305,
          "quote": "| `O:OperationKind.value.operation_contract_ref` | 1 |  |  | `OperationContract` | `B_adopted` |\n| `O:OperationKind.value.target_sort_ref` | 1 |  |  | `TargetSort` | `B_adopted` |\n| `O:OperationKind.value.invalidation_ref` | 1 |  |  | `InvalidationContract` | `B_adopted` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 303
        }
      ],
      "key": "operation_kind",
      "label": "OperationKind"
    },
    {
      "conditions": [],
      "definition": "Separately identified domain-operation instance, binding an operation kind, target subject, effect territory, operation contract and invalidation contract.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 310,
          "quote": "| `O:EffectOperation.value.operation_kind_ref` | 1 | `O` | `OperationKind` |  | `B_model` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 306
        }
      ],
      "key": "effect_operation",
      "label": "EffectOperation"
    },
    {
      "conditions": [],
      "definition": "Owner-issued operation grant identifying its issuer, subject binding, nonempty allowed operation-kind population, allowed effect territory and invalidation contract.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 315,
          "quote": "| `O:OperationGrant.value.allowed_operation_kind_refs` | 1..* | `O` | `OperationKind` |  | `B_model` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 311
        }
      ],
      "key": "operation_grant",
      "label": "OperationGrant"
    },
    {
      "conditions": [],
      "definition": "Immutable invocation record identifying occurrence, operation, executor, actor, grant, territory and inputs; it contains no future disposition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1355,
          "quote": "The\nimmutable `EffectInvocation` contains no future disposition, and\n`EffectDisposition` records the later outcome without rewriting the\ninvocation (P3, P6).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FMutable-subject%20effect%20relation",
          "start_line": 1352
        }
      ],
      "key": "effect_invocation",
      "label": "EffectInvocation"
    },
    {
      "conditions": [],
      "definition": "Later outcome record with closed cases no_effect, completed_effect, partial_effect and refused_effect, distinguished by dispatch, observation, evidence, residual and stop requirements.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1349,
          "quote": "The disposition law is closed (P5, P6):",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FMutable-subject%20effect%20relation",
          "start_line": 1339
        }
      ],
      "key": "effect_disposition",
      "label": "EffectDisposition"
    },
    {
      "conditions": [],
      "definition": "Evidence tied to one invocation, with one or more evidence references and an observation-limit reference.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 329,
          "quote": "| `O:EffectEvidence.value.invocation_ref` | 1 | `O` | `EffectInvocation` |  | `B_model` |\n| `O:EffectEvidence.value.evidence_refs` | 1..* |  |  | `Evidence` | `B_adopted` |\n| `O:EffectEvidence.value.observation_limit_ref` | 1 |  |  | `ObservationLimit` | `B_adopted` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 327
        }
      ],
      "key": "effect_evidence",
      "label": "EffectEvidence"
    },
    {
      "conditions": [],
      "definition": "Candidate claim about a typed relation with already-existing endpoints, exact qualifiers, claimant, claim basis and source frontier. Construction does not constitute admission.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1232,
          "quote": "The endpoints of a pre-admission `RelationClaim` already exist.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FCandidate%2C%20judgment%2C%20event%20and%20relation%20separation",
          "start_line": 1229
        }
      ],
      "key": "relation_claim",
      "label": "RelationClaim"
    },
    {
      "conditions": [],
      "definition": "FrameworkEvent binds an unchanged payload and its digest, declared scope, exact event kind, source frontier and applicable occurrence, claim and judgment references. EventKind_occurrence contains exactly urn:stdo:traversal-occurrence:event-kind:claim-admission, urn:stdo:traversal-occurrence:event-kind:occurrence-admission, urn:stdo:traversal-occurrence:event-kind:effect-disposition and urn:stdo:traversal-occurrence:event-kind:external-fact-admission.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 532,
          "quote": "EventKind_occurrence = {\n  urn:stdo:traversal-occurrence:event-kind:claim-admission,\n  urn:stdo:traversal-occurrence:event-kind:occurrence-admission,\n  urn:stdo:traversal-occurrence:event-kind:effect-disposition,\n  urn:stdo:traversal-occurrence:event-kind:external-fact-admission\n}",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20event-kind%20population",
          "start_line": 527
        }
      ],
      "key": "framework_event",
      "label": "FrameworkEvent and event-kind population"
    },
    {
      "conditions": [],
      "definition": "Immutable binding of the complete evaluated event member set, exact basis and declared precedence law. Its identity includes profile basis, scope, precedence law, sorted event identities and event content digests.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1421,
          "quote": "An `EventFrontier` binds the complete member set of events evaluated, its\nexact basis and its declared precedence law.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FEvent%20frontier%20and%20projection",
          "start_line": 1410
        }
      ],
      "key": "event_frontier",
      "label": "EventFrontier"
    },
    {
      "conditions": [],
      "definition": "Immutable projection binding exactly one unchanged frontier, projection rule, selected relation identities, boundary identities and residual identities; a projection judgment binds its unchanged identity and digest.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1421,
          "quote": "Projection identity binds the exact\nfrontier, the projection rule, and the selected relation, boundary and\nresidual ids (P3, P4b).",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FEvent%20frontier%20and%20projection",
          "start_line": 1419
        }
      ],
      "key": "projection",
      "label": "Projection"
    },
    {
      "conditions": [],
      "definition": "Seven-member semantic admission subject comprising unchanged claim, claim judgment, event, event judgment, materialized relation, source frontier and successor frontier, itself subject to a distinct cut judgment.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1148,
          "quote": "  -> SemanticAdmissionCut a = (c, j_c, e, j_e, r, F_k, F_k_plus_1)\n  -> Judgment j_a over unchanged a",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FCandidate%2C%20judgment%2C%20event%20and%20relation%20separation",
          "start_line": 1147
        }
      ],
      "key": "semantic_admission_cut",
      "label": "SemanticAdmissionCut"
    },
    {
      "conditions": [],
      "definition": "Exact readiness subject binding occurrence, stable subject binding, pre-observation, invocation, operation, grant, territory and currentness/invalidation state.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1293,
          "quote": "s_n = EffectSubject(o_n, b_W, q_n, inv_n, op_n, g_n, territory_n, invalidation_n)\nj_ready = judge_effect_readiness(s_n)",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FMutable-subject%20effect%20relation",
          "start_line": 1292
        }
      ],
      "key": "effect_subject",
      "label": "EffectSubject"
    },
    {
      "conditions": [],
      "definition": "Transition-evaluation subject binding occurrence, subject binding, pre-observation, optional post-observation, intended outcome, effect disposition and effect evidence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 372,
          "quote": "| `O:TransitionSubject.value.post_observation_ref_or_none` | 0..1 | `O` | `Observation` |  | `B_model` |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20semantic-object%20sorts%2FFinite%20reference-domain%20table",
          "start_line": 366
        }
      ],
      "key": "transition_subject",
      "label": "TransitionSubject"
    },
    {
      "conditions": [],
      "definition": "ProfileRecordRef is the closed union of profile semantic-object records O and exact inherited E, C, L, X, V, T and J populations in the same model, not a ninth record kind.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 586,
          "quote": "`ProfileRecordRef` is the closed union of the profile semantic-object\nrecords in `O` and the exact inherited `E`, `C`, `L`, `X`, `V`, `T` and `J`\npopulations in the same model; it introduces no ninth record kind.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20relation%20families",
          "start_line": 582
        }
      ],
      "key": "profile_record",
      "label": "ProfileRecordRef and inherited populations"
    },
    {
      "conditions": [],
      "definition": "Exact inherited Traversal record. The profile references only F_D, F_P and F_H from b_ac, preserving their imported laws. Traversal classification is distinct from a domain operation and its authorization or execution.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1083,
          "quote": "`Sigma_occurrence.FunctorKind` contains exact refs to `F_D`, `F_P` and\n`F_H` from `b_ac` and no other functor kind.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20constraint%2C%20judgment%2C%20residual%20and%20stop%20kinds",
          "start_line": 1081
        }
      ],
      "key": "inherited_traversal",
      "label": "Inherited Traversal and functor kinds"
    },
    {
      "conditions": [],
      "definition": "Exact inherited TypedRelation; its kind selects a closed qualifier contract governing direction, cardinality, basis, preservation, refusal and invalidation. The 24 core kinds are described by the local typed relations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 591,
          "quote": "Each relation is an exact `TypedRelation`. Its qualifiers close direction,\ncardinality, basis, preservation, refusal and invalidation semantics;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20relation%20families",
          "start_line": 588
        }
      ],
      "key": "typed_relation",
      "label": "TypedRelation"
    },
    {
      "conditions": [],
      "definition": "Inherited Judgment preserves its subject identity and digest and carries evaluator, authority, evidence, provenance and decision coordinate. Closed kinds are model_validation, occurrence_admission, event_admission, claim_admission, semantic_cut_admission, effect_readiness, transition_evaluation and frontier_projection.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 809,
          "quote": "Each is an inherited `Judgment` and so carries the unchanged subject id\nand digest, evaluator, authority, evidence, provenance and decision\ncoordinate.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20constraint%2C%20judgment%2C%20residual%20and%20stop%20kinds",
          "start_line": 806
        }
      ],
      "key": "profile_judgment",
      "label": "Source-defined Judgment"
    },
    {
      "conditions": [],
      "definition": "The profile's closed constraint, residual, stop and decision domains and their predicate-specific core-result mappings. Constraint kinds: identity_dependency_acyclic, occurrence_causation_acyclic, event_causation_acyclic, occurrence_seed_complete, relation_claim_admissible, semantic_cut_complete, pre_effect_current, operation_grant_contains_effect, event_scope_compatible, frontier_complete, transition_subject_complete. Residual kinds: unobserved_subject_state, partial_effect, unresolved_cause, unresolved_scope, competing_lineage, stale_frontier, stale_currentness, unobserved_external_mutation. Stop kinds: hold, gap, refusal, invalid_basis, out_of_scope, partial_effect.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 791,
          "quote": "Every constraint predicate returns exactly one of `satisfied`,\n`falsified`, `indeterminate` or `invalid_basis`.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/TRAVERSAL_OCCURRENCE.md#TRAVERSAL_OCCURRENCE%2FClosed%20constraint%2C%20judgment%2C%20residual%20and%20stop%20kinds",
          "start_line": 777
        }
      ],
      "key": "occurrence_results",
      "label": "Occurrence-profile result domains"
    },
    {
